begin;

alter table public.restaurant_subscription_invoices add column if not exists refunded_pence integer not null default 0 check(refunded_pence>=0);

create or replace function public.restaurant_member_has_permission(p_permission text) returns boolean language plpgsql stable security definer set search_path='' as $$declare allowed boolean;begin select case when rm.role='owner' then true else(rm.permissions?p_permission) or coalesce(tr.permissions?p_permission,false) end into allowed from public.restaurant_members rm left join public.restaurant_team_roles tr on tr.id=rm.custom_role_id and tr.restaurant_id=rm.restaurant_id where rm.user_id=(select auth.uid()) and rm.status='active' order by rm.created_at limit 1;return coalesce(allowed,false);end$$;

create or replace function public.update_restaurant_enterprise_settings(p_patch jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare rid uuid;settings public.restaurant_enterprise_settings%rowtype;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and role='owner' and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant owner access required' using errcode='42501';end if;if p_patch?'white_label_domain' and not coalesce((private.restaurant_plan_feature(rid,'white_label')#>>'{}')::boolean,false) then raise exception 'White label is not included in this plan' using errcode='42501';end if;if(p_patch?'custom_brand_name' or p_patch?'custom_logo_url' or p_patch?'custom_primary_colour') and not coalesce((private.restaurant_plan_feature(rid,'custom_branding')#>>'{}')::boolean,false) then raise exception 'Custom branding is not included in this plan' using errcode='42501';end if;if p_patch?'sso_enabled' and coalesce((p_patch->>'sso_enabled')::boolean,false) and not coalesce((private.restaurant_plan_feature(rid,'sso_ready')#>>'{}')::boolean,false) then raise exception 'SSO is not included in this plan' using errcode='42501';end if;insert into public.restaurant_enterprise_settings(restaurant_id,custom_brand_name,custom_logo_url,custom_primary_colour,white_label_domain,sso_enabled,sso_provider,sso_metadata,support_level,priority_processing,updated_at) values(rid,p_patch->>'custom_brand_name',p_patch->>'custom_logo_url',p_patch->>'custom_primary_colour',nullif(lower(trim(p_patch->>'white_label_domain')),''),coalesce((p_patch->>'sso_enabled')::boolean,false),p_patch->>'sso_provider',coalesce(p_patch->'sso_metadata','{}'::jsonb),coalesce(p_patch->>'support_level','standard'),coalesce((p_patch->>'priority_processing')::boolean,false),now()) on conflict(restaurant_id) do update set custom_brand_name=case when p_patch?'custom_brand_name' then excluded.custom_brand_name else restaurant_enterprise_settings.custom_brand_name end,custom_logo_url=case when p_patch?'custom_logo_url' then excluded.custom_logo_url else restaurant_enterprise_settings.custom_logo_url end,custom_primary_colour=case when p_patch?'custom_primary_colour' then excluded.custom_primary_colour else restaurant_enterprise_settings.custom_primary_colour end,white_label_domain=case when p_patch?'white_label_domain' then excluded.white_label_domain else restaurant_enterprise_settings.white_label_domain end,sso_enabled=case when p_patch?'sso_enabled' then excluded.sso_enabled else restaurant_enterprise_settings.sso_enabled end,sso_provider=case when p_patch?'sso_provider' then excluded.sso_provider else restaurant_enterprise_settings.sso_provider end,sso_metadata=case when p_patch?'sso_metadata' then excluded.sso_metadata else restaurant_enterprise_settings.sso_metadata end,updated_at=now() returning * into settings;return to_jsonb(settings);end$$;

create or replace function private.enforce_subscription_feature_trigger() returns trigger language plpgsql security definer set search_path='' as $$declare rid uuid:=new.restaurant_id;feature text;enabled boolean;begin if tg_table_name='restaurant_loyalty_rewards' then feature:='loyalty';elsif tg_table_name='restaurant_stamp_programs' then feature:='stamp_cards';elsif tg_table_name='restaurant_referral_programs' then feature:='referrals';elsif tg_table_name='restaurant_birthday_programs' then feature:='birthday_rewards';elsif tg_table_name='restaurant_vip_programs' then feature:='vip';elsif tg_table_name='restaurant_challenges' then feature:='challenges';elsif tg_table_name='restaurant_marketing_automations' then feature:='marketing_automation';else return new;end if;if not exists(select 1 from public.restaurant_subscriptions where restaurant_id=rid) then return new;end if;enabled:=coalesce((private.restaurant_plan_feature(rid,feature)#>>'{}')::boolean,false);if not enabled then raise exception 'Feature % is not included in the current subscription plan',feature using errcode='42501';end if;return new;end$$;
drop trigger if exists gate_loyalty_subscription_feature on public.restaurant_loyalty_rewards;create trigger gate_loyalty_subscription_feature before insert on public.restaurant_loyalty_rewards for each row execute function private.enforce_subscription_feature_trigger();
drop trigger if exists gate_stamp_subscription_feature on public.restaurant_stamp_programs;create trigger gate_stamp_subscription_feature before insert on public.restaurant_stamp_programs for each row execute function private.enforce_subscription_feature_trigger();
drop trigger if exists gate_referral_subscription_feature on public.restaurant_referral_programs;create trigger gate_referral_subscription_feature before insert on public.restaurant_referral_programs for each row execute function private.enforce_subscription_feature_trigger();
drop trigger if exists gate_birthday_subscription_feature on public.restaurant_birthday_programs;create trigger gate_birthday_subscription_feature before insert on public.restaurant_birthday_programs for each row execute function private.enforce_subscription_feature_trigger();
drop trigger if exists gate_vip_subscription_feature on public.restaurant_vip_programs;create trigger gate_vip_subscription_feature before insert on public.restaurant_vip_programs for each row execute function private.enforce_subscription_feature_trigger();
drop trigger if exists gate_challenge_subscription_feature on public.restaurant_challenges;create trigger gate_challenge_subscription_feature before insert on public.restaurant_challenges for each row execute function private.enforce_subscription_feature_trigger();
drop trigger if exists gate_automation_subscription_feature on public.restaurant_marketing_automations;create trigger gate_automation_subscription_feature before insert on public.restaurant_marketing_automations for each row execute function private.enforce_subscription_feature_trigger();

create or replace function public.get_platform_subscription_analytics() returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if not private.platform_admin_has_permission('finance:view') then raise exception 'Finance access required' using errcode='42501';end if;select jsonb_build_object('mrr_pence',coalesce(sum(case when s.status in('active','trialing','past_due') then case when s.custom_price_pence is not null then case when s.billing_interval='annual' then round(s.custom_price_pence/12.0)::bigint else s.custom_price_pence end when s.billing_interval='annual' then round(coalesce(p.annual_price_pence,0)/12.0)::bigint else p.monthly_price_pence end else 0 end),0),'arr_pence',coalesce(sum(case when s.status in('active','trialing','past_due') then case when s.custom_price_pence is not null then case when s.billing_interval='annual' then s.custom_price_pence else s.custom_price_pence*12 end when s.billing_interval='annual' then coalesce(p.annual_price_pence,0) else p.monthly_price_pence*12 end else 0 end),0),'active_subscribers',count(*) filter(where s.status='active'),'trialing',count(*) filter(where s.status='trialing'),'past_due',count(*) filter(where s.status='past_due'),'cancelled_30d',(select count(*) from public.restaurant_subscription_cancellations where requested_at>=now()-interval '30 days'),'trial_conversions_30d',(select count(distinct restaurant_id) from public.restaurant_subscription_events where event_type in('invoice_payment_succeeded','subscription_renewed') and created_at>=now()-interval '30 days' and restaurant_id in(select restaurant_id from public.restaurant_subscription_trial_history)),'subscriber_growth_30d',(select count(*) from public.restaurant_subscriptions where created_at>=now()-interval '30 days'),'plan_distribution',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'subscribers',x.subscribers) order by x.subscribers desc) from(select p2.code,p2.name,count(s2.id) subscribers from public.subscription_plans p2 left join public.restaurant_subscriptions s2 on s2.plan_id=p2.id and s2.status in('active','trialing','past_due') group by p2.id,p2.code,p2.name)x),'[]'::jsonb),'cancellation_reasons',coalesce((select jsonb_agg(jsonb_build_object('reason',x.reason_code,'count',x.n) order by x.n desc) from(select reason_code,count(*) n from public.restaurant_subscription_cancellations where requested_at>=now()-interval '90 days' group by reason_code)x),'[]'::jsonb),'revenue_per_restaurant',coalesce((select jsonb_agg(jsonb_build_object('restaurant_id',x.restaurant_id,'restaurant_name',x.name,'revenue_pence',x.revenue) order by x.revenue desc) from(select r.id restaurant_id,r.name,coalesce(sum(greatest(i.amount_paid_pence-i.refunded_pence,0)),0) revenue from public.restaurants r left join public.restaurant_subscription_invoices i on i.restaurant_id=r.id and i.paid_at>=now()-interval '12 months' group by r.id,r.name order by revenue desc limit 100)x),'[]'::jsonb),'net_subscription_revenue_12m_pence',(select coalesce(sum(greatest(amount_paid_pence-refunded_pence,0)),0) from public.restaurant_subscription_invoices where paid_at>=now()-interval '12 months'),'estimated_ltv_pence',case when(select count(*) from public.restaurant_subscription_cancellations where requested_at>=now()-interval '12 months')=0 then null else round((coalesce(sum(case when s.status='active' then case when s.billing_interval='annual' then coalesce(p.annual_price_pence,0)/12.0 else p.monthly_price_pence end else 0 end),0)/greatest(count(*) filter(where s.status='active'),1))/greatest((select count(*)::numeric from public.restaurant_subscription_cancellations where requested_at>=now()-interval '12 months')/greatest(count(*) filter(where s.status='active'),1),0.01))::bigint end) into result from public.restaurant_subscriptions s left join public.subscription_plans p on p.id=s.plan_id;return result;end$$;

revoke all on function public.restaurant_member_has_permission(text),public.update_restaurant_enterprise_settings(jsonb) from public,anon,authenticated;
grant execute on function public.restaurant_member_has_permission(text),public.update_restaurant_enterprise_settings(jsonb) to authenticated;

commit;
